#!/usr/bin/env python3"""Messenger Terminal - Robust Facebook Messenger Automation Controller=====================================================================A comprehensive terminal application for controlling Facebook Messenger outreachwith duplicate prevention, rate limiting, and detailed logging.Features:- Duplicate message prevention (tracks sent messages)- Configurable batch sizes and delays- Dry-run mode for testing- Interactive message preview- Comprehensive logging- Resume capability- Error tracking and recovery"""import subprocessimport timeimport randomimport csvimport jsonimport osimport sysimport loggingimport urllib.requestfrom pathlib import Pathfrom dataclasses import dataclass, asdictfrom typing import List, Optional, Dict, Tuplefrom datetime import datetimefrom collections import defaultdict# ConfigurationCHROME_EXE = r"C:\Program Files\Google\Chrome\Application\chrome.exe"USER_DATA_DIR = Path.home() / "AppData" / "Local" / "Google" / "Chrome" / "User Data"PROFILE = "Profile 3"DATA_DIR = Path(__file__).parent.resolve()CSV_PATH = DATA_DIR / "fbfriends.csv"LOG_PATH = DATA_DIR / "messenger_terminal.log"STATE_PATH = DATA_DIR / "messenger_state.json"HISTORY_PATH = DATA_DIR / "message_history.json"# Setup logginglogging.basicConfig(    level=logging.INFO,    format='%(asctime)s [%(levelname)s] %(message)s',    handlers=[        logging.FileHandler(LOG_PATH),        logging.StreamHandler(sys.stdout)    ])logger = logging.getLogger('MessengerTerminal')@dataclassclass Contact:    """Represents a Facebook contact"""    fb_usr_id: str    fb_first_name: str    fb_last_name: str    fb_name: str    fb_profile_id: str    message_sent: str    sent_at: str    last_error: str        @property    def messenger_url(self) -> str:        """Generate Messenger URL for this contact"""        profile_id = self.fb_profile_id.lstrip('/')        return f"https://www.messenger.com/t/{profile_id}"        @property    def is_sent(self) -> bool:        """Check if message has been sent"""        return self.message_sent.lower() == 'true' and bool(self.sent_at)        @property    def full_name(self) -> str:        """Get full name"""        return f"{self.fb_first_name} {self.fb_last_name}".strip() or self.fb_name@dataclassclass Event:    """Represents an event to promote"""    title: str    url: str    description: str    date: str = ""    venue: str = ""@dataclassclass MessageSent:    """Tracks a sent message"""    contact_id: str    contact_name: str    sent_at: str    message_hash: str    event_url: strclass MessageHistory:    """Manages message history to prevent duplicates"""        def __init__(self, history_file: Path):        self.history_file = history_file        self.history: Dict[str, List[MessageSent]] = defaultdict(list)        self.load()        def load(self):        """Load message history from file"""        if self.history_file.exists():            try:                with open(self.history_file, 'r', encoding='utf-8') as f:                    data = json.load(f)                    for contact_id, records in data.items():                        self.history[contact_id] = [                            MessageSent(**record) for record in records                        ]                logger.info(f"Loaded message history for {len(self.history)} contacts")            except Exception as e:                logger.error(f"Failed to load history: {e}")        def save(self):        """Save message history to file"""        try:            data = {}            for contact_id, records in self.history.items():                data[contact_id] = [asdict(record) for record in records]                        with open(self.history_file, 'w', encoding='utf-8') as f:                json.dump(data, f, indent=2)        except Exception as e:            logger.error(f"Failed to save history: {e}")        def has_sent_to(self, contact_id: str, event_url: str = None) -> bool:        """Check if we've sent to this contact"""        if contact_id not in self.history:            return False                if event_url:            return any(                record.event_url == event_url                 for record in self.history[contact_id]            )                return len(self.history[contact_id]) > 0        def record_sent(self, contact: Contact, event_url: str, message: str):        """Record a sent message"""        record = MessageSent(            contact_id=contact.fb_profile_id,            contact_name=contact.fb_name,            sent_at=datetime.utcnow().isoformat(),            message_hash=hash(message) & 0xFFFFFFFF,            event_url=event_url        )        self.history[contact.fb_profile_id].append(record)        self.save()class MessengerTerminal:    """Main terminal application"""        def __init__(self):        self.event = Event(            title="Cosmic Blues Band Live",            url="https://www.facebook.com/events/971902445574502",            description="A night of blues and roots music with the Cosmic Blues Band!",            date="",            venue=""        )        self.history = MessageHistory(HISTORY_PATH)        self.config = self.load_config()        self.sent_count = 0        self.error_count = 0        self.session_start = datetime.now()                DATA_DIR.mkdir(parents=True, exist_ok=True)        def load_config(self) -> Dict:        """Load or create configuration"""        config_path = DATA_DIR / "config.json"        default_config = {            "batch_size": 5,            "min_delay": 30,            "max_delay": 120,            "page_load_wait": 60,            "typing_delay": 3,            "auto_confirm": False,            "message_styles": [                "personal",                "casual",                 "exciting",                "fomo",                "warm"            ]        }                if config_path.exists():            try:                with open(config_path, 'r') as f:                    return {**default_config, **json.load(f)}            except:                pass                return default_config        def save_config(self):        """Save configuration"""        config_path = DATA_DIR / "config.json"        with open(config_path, 'w') as f:            json.dump(self.config, f, indent=2)        def clear_screen(self):        """Clear terminal screen"""        os.system('cls' if os.name == 'nt' else 'clear')        def print_header(self):        """Print application header"""        print("=" * 70)        print("  FACEBOOK MESSENGER AUTOMATION TERMINAL v2.0")        print("=" * 70)        print(f"  Session Started: {self.session_start.strftime('%Y-%m-%d %H:%M:%S')}")        print(f"  Data Directory: {DATA_DIR.absolute()}")        print(f"  Event: {self.event.title}")        print("=" * 70)        print()        def load_ny_profiles(self) -> set:        """Load profile IDs from contacts/fb_friend.csv that are in NY area"""        ny_profiles = set()        friend_csv = DATA_DIR / "contacts" / "fb_friend.csv"        if not friend_csv.exists():            return ny_profiles        ny_kw = ['new york', 'nyc', 'brooklyn', 'manhattan', 'queens', 'bronx', 'staten island', 'astoria', 'harlem', 'long island', 'hoboken', 'jersey city', 'yonkers', 'white plains', ', ny']        try:            with open(friend_csv, 'r', encoding='utf-8', errors='replace') as f:                reader = csv.reader(f)                for row in reader:                    if len(row) < 5: continue                    loc = (row[3] if len(row) > 3 else '').lower()                    pid = (row[4] if len(row) > 4 else '').lstrip('/')                    if pid and any(k in loc for k in ny_kw):                        ny_profiles.add(pid)            print(f"   NY filter: {len(ny_profiles)} NY-area profiles")        except: pass        return ny_profiles        def load_contacts(self, limit: int = 0, only_pending: bool = True, ny_only: bool = True) -> List[Contact]:        """Load contacts from CSV, optionally filtered to NY area"""        contacts = []                ny_profiles = self.load_ny_profiles() if ny_only else None             if not CSV_PATH.exists():          logger.error(f"CSV file not found: {CSV_PATH}")          return contacts            try:          with open(CSV_PATH, 'r', encoding='utf-8') as f:              reader = csv.DictReader(f)              for row in reader:                  if only_pending and row.get('message_sent') in ('true', 'bad'):                      continue                                    profile_id = row.get('fb_profile_id', '').lstrip('/')                  if self.history.has_sent_to(profile_id, self.event.url):                      continue                                    # NY filter: skip if not in NY profiles                  if ny_only and ny_profiles and profile_id not in ny_profiles:                      continue                                    contact = Contact(                      fb_usr_id=row.get('fb_usr_id', ''),                      fb_first_name=row.get('fb_first_name', ''),                      fb_last_name=row.get('fb_last_name', ''),                      fb_name=row.get('fb_name', ''),                      fb_profile_id=profile_id,                      message_sent=row.get('message_sent', ''),                      sent_at=row.get('sent_at', ''),                      last_error=row.get('last_error', '')                  )                  contacts.append(contact)                                    if limit > 0 and len(contacts) >= limit:                      break      except Exception as e:          logger.error(f"Error loading contacts: {e}")            return contacts        def generate_message(self, contact: Contact, style: str = None) -> str:        """Generate a personalized message"""        first_name = contact.fb_first_name or contact.fb_name.split()[0]        url = self.event.url                templates = {            "personal": [                f"Hey {first_name}!\n\nPutting together a blues show and immediately thought of you. Come hang! Also, hitting \"Interested\" on the event page helps other blues fans discover it.\n\n{url}",                f"Hi {first_name}!\n\nWe've got a blues night coming up that I thought you'd dig. Would love to see you there! If you can, click \"Interested\" on the event page—it really helps spread the word.\n\n{url}",            ],            "casual": [                f"Hey {first_name}!\n\nHope you're doing well! I'm organizing a blues show and wanted to invite you. Check it out when you get a chance, and if you're interested, click the \"Interested\" button on the event page - it helps with visibility!\n\n{url}",            ],            "exciting": [                f"Hey {first_name}! Big news - we're putting together an amazing blues night! Think you'd really love the vibe. Come through! And if you click \"Interested\" on the event page, it helps other blues lovers find us.\n\n{url}",            ],            "fomo": [                f"Hi {first_name}!\n\nDon't miss out on this blues night we've got coming up! Great music, good times. Would love to have you there. Click \"Interested\" on the event page to help spread the word to other blues fans!\n\n{url}",            ],            "warm": [                f"Hi {first_name}! Thinking of you and wanted to personally invite you to our upcoming blues show. It would mean a lot to have you there. If you can, click \"Interested\" on the event page - every bit helps!\n\n{url}",            ],            "supportive": [                f"Hey {first_name}!\n\nAs a fellow music lover, I wanted to reach out about our blues show. Your support would mean the world to us! Click \"Interested\" on the event page to help us reach more blues fans.\n\n{url}",            ],            "community": [                f"Hi {first_name}!\n\nWe're building something special with this blues show and would love for you to be part of it. Come join the community! Help us spread the word by clicking \"Interested\" on the event page.\n\n{url}",            ],            "direct": [                f"Hey {first_name},\n\nBlues show coming up - you're invited! Click \"Interested\" on the event page to help with visibility.\n\n{url}",            ],            "curious": [                f"Hey {first_name}!\n\nEver been to a live blues show that just hit different? We're creating one of those nights. Curious if you'd be into it? Click \"Interested\" on the event page and help other blues fans discover it too!\n\n{url}",            ],            "favor": [                f"Hi {first_name}!\n\nQuick favor - would you mind checking out our upcoming blues event? I'd love your support! Clicking \"Interested\" on the event page really helps with visibility for blues fans in the area.\n\n{url}",            ]        }                if style and style in templates:            messages = templates[style]        else:            allowed_styles = self.config.get('message_styles', list(templates.keys()))            available = [s for s in allowed_styles if s in templates]            if not available:                available = list(templates.keys())            messages = templates[random.choice(available)]                return random.choice(messages)        def is_chrome_connected(self) -> bool:        """Check if Chrome debug port is still responding"""        try:            urllib.request.urlopen("http://127.0.0.1:9222/json/version", timeout=3)            return True        except:            return False        def ensure_chrome_open(self, url: str = None):        """Check if Chrome is open, relaunch if closed"""        if self.is_chrome_connected():            return True                print("\n   Chrome was closed! Relaunching...")        if url:            self.launch_chrome(url)        else:            self.launch_chrome("https://www.messenger.com")        return self.is_chrome_connected()        def mark_contact_bad(self, contact: Contact, reason: str):        """Mark a contact as bad profile - sets message_sent=true with error in last_error        so it's permanently skipped from future runs"""        if not CSV_PATH.exists():            return                try:            rows = []            with open(CSV_PATH, 'r', encoding='utf-8') as f:                reader = csv.DictReader(f)                fieldnames = reader.fieldnames                for row in reader:                    row_profile = row.get('fb_profile_id', '').lstrip('/')                    contact_profile = contact.fb_profile_id.lstrip('/')                    if row_profile == contact_profile and row_profile:                        row['message_sent'] = 'bad'                        row['last_error'] = f"BAD PROFILE: {reason}"                    rows.append(row)                        with open(CSV_PATH, 'w', newline='', encoding='utf-8') as f:                writer = csv.DictWriter(f, fieldnames=fieldnames)                writer.writeheader()                writer.writerows(rows)                        print(f"   Marked {contact.fb_name} as BAD PROFILE - will be skipped permanently")                            except Exception as e:            logger.error(f"Failed to mark bad contact: {e}")        def update_csv_status(self, contact: Contact, success: bool, error: str = None):        """Update CSV with send status - matches by profile_id (handles leading slash)"""        if not CSV_PATH.exists():            return                try:            rows = []            with open(CSV_PATH, 'r', encoding='utf-8') as f:                reader = csv.DictReader(f)                fieldnames = reader.fieldnames                for row in reader:                    # Match by profile_id - handle leading slash differences                    row_profile = row.get('fb_profile_id', '').lstrip('/')                    contact_profile = contact.fb_profile_id.lstrip('/')                    if row_profile == contact_profile and row_profile:                        if success:                            row['message_sent'] = 'true'                            row['sent_at'] = datetime.utcnow().isoformat()                            row['last_error'] = ''                        else:                            row['message_sent'] = 'false'                            row['last_error'] = error if error else ''                    rows.append(row)                        with open(CSV_PATH, 'w', newline='', encoding='utf-8') as f:                writer = csv.DictWriter(f, fieldnames=fieldnames)                writer.writeheader()                writer.writerows(rows)                            except Exception as e:            logger.error(f"Failed to update CSV: {e}")        def launch_chrome(self, url: str):        """Launch Chrome with debug port"""                user_data = str(Path.home() / "AppData" / "Local" / "Google" / "Chrome" / "User Data")                print("   Launching Chrome...")                # Use PowerShell Start-Process - properly escape each argument separately        print("   Launching Chrome...")                # Build ArgumentList as separate quoted items so spaces in paths don't split        ps_args = [            f"'--user-data-dir={user_data}'",            f"'--profile-directory={PROFILE}'",            "'--start-maximized'",            "'--disable-blink-features=AutomationControlled'",            "'--remote-debugging-port=9222'",            "'--remote-allow-origins=*'",            "'--no-first-run'",            "'--no-default-browser-check'",            "'--no-restore-last-session'",            f"'{url}'"        ]        args_list = ",".join(ps_args)                subprocess.Popen([            'powershell', '-Command',            f"Start-Process -FilePath '{CHROME_EXE}' -ArgumentList {args_list}"        ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)                # Wait for debug port        print("   Waiting for Chrome debug port...")        for i in range(20):            time.sleep(2)            try:                urllib.request.urlopen("http://127.0.0.1:9222/json/version", timeout=2)                print(f"   Chrome is ready! ({(i+1)*2}s)")                return True            except:                if i < 19:                    print(f"   waiting ({(i+1)*2}s)...")                else:                    print("   WARNING: Debug port not responding!")                    print("   Make sure you ran via run_messenger_terminal.bat")                    print("   Or manually close Chrome and try again.")                    return False                return None        def create_playwright_script(self, message: str, messenger_url: str = None, contact_name: str = None) -> str:        """Create Node.js Playwright script - navigates to contact's URL and types message"""        escaped_message = message.replace('\\', '\\\\').replace('`', '\\`').replace('$', '\\$')                # Safe filename for screenshots        safe_name = (contact_name or 'unknown').replace(' ', '_').replace('.', '_').replace('/', '_')                # Navigation code if URL provided        nav_code = ''        if messenger_url:            nav_code = f"""        // Navigate to this contact's conversation        console.log('Navigating to: {messenger_url}');        await page.goto('{messenger_url}', {{ waitUntil: 'domcontentloaded', timeout: 10000 }}).catch(e => {{            console.log('Navigation slow, continuing anyway...');        }});        console.log('Page loaded, waiting for render...');                // Take BEFORE screenshot        try {{            await page.screenshot({{ path: 'before_{safe_name}.png', fullPage: false }});            console.log('Before screenshot saved');        }} catch(e) {{ console.log('Screenshot failed'); }}                // DETECT AND CLICK CONTINUE BUTTON        // Facebook shows a 'Continue' or 'Continue as' button on some conversations        console.log('Checking for Continue button...');        let continueClicked = false;                // Try 5 times with 2s gaps — button may appear after a delay        for (let attempt = 0; attempt < 5; attempt++) {{            try {{                const buttons = await page.locator('div[role="button"], button').all();                for (const btn of buttons) {{                    const text = await btn.textContent().catch(() => '');                    const isVisible = await btn.isVisible().catch(() => false);                    if (isVisible && text.toLowerCase().includes('continue')) {{                        console.log('Continue button found: ' + text + ' — clicking...');                        await btn.click();                        continueClicked = true;                        console.log('Continue button clicked!');                        await page.waitForTimeout(3000);                        break;                    }}                }}                if (continueClicked) break;                if (attempt < 4) await page.waitForTimeout(2000);            }} catch(e) {{}}        }}                if (continueClicked) {{            console.log('Conversation loading after Continue...');            try {{ await page.screenshot({{ path: 'after_continue_{safe_name}.png', fullPage: false }}); }} catch(e) {{}}        }} else {{            console.log('No Continue button found');        }}                // Wait for the textbox to be visible (page fully rendered)        try {{            await page.waitForSelector('div[role="textbox"]', {{ state: 'visible', timeout: 15000 }});            console.log('Textbox visible, page rendered');        }} catch(e) {{            console.log('Textbox not found, waiting 5s...');            await page.waitForTimeout(5000);        }}                // CHECK 1: Has the event link already been sent to this contact?        console.log('Checking if event already sent...');        const pageText = await page.evaluate(() => document.body.innerText).catch(() => '');        const eventUrl = '{self.event.url}';        if (pageText.includes(eventUrl) || pageText.includes('971902445574502')) {{            console.log('ALREADY_SENT: Event link found in conversation');            await page.screenshot({{ path: 'already_sent_{safe_name}.png', fullPage: false }}).catch(() => {{}});            process.exit(2);  // Exit code 2 = already sent        }}        console.log('Event not previously sent');"""                return f'''const {{ chromium }} = require('playwright');(async () => {{    console.log('Connecting to Chrome...');        try {{        const browser = await chromium.connectOverCDP('http://127.0.0.1:9222');        const context = browser.contexts()[0];                // Find the messenger page        let page = null;        for (const p of context.pages()) {{            try {{                if (p.url().includes('messenger.com')) {{ page = p; break; }}            }} catch(e) {{}}        }}        if (!page) page = context.pages()[0];                console.log('Connected. Current URL:', page.url());        {nav_code}                // Find the message composer        console.log('Looking for message composer...');                const textbox = page.locator('div[role="textbox"]').first();        await textbox.waitFor({{ state: 'visible', timeout: 8000 }}).catch(e => {{            console.error('ERROR: Message composer not found after 8s');            process.exit(1);        }});        console.log('Found textbox');                // Click to focus and wait for it to be ready        console.log('Clicking composer...');        await textbox.click();        await page.waitForTimeout(500);                // Use keyboard.type() - simulates real keystrokes        console.log('Typing message...');        await page.keyboard.type(`{escaped_message}`, {{ delay: 3 }});        await page.waitForTimeout(300);                // Press Enter to send the message        console.log('Sending message...');        await page.keyboard.press('Enter');                console.log('SUCCESS: Message sent!');                // Take AFTER screenshot        try {{            await page.screenshot({{ path: 'after_{safe_name}.png', fullPage: false }});            console.log('After screenshot saved: after_{safe_name}.png');        }} catch(e) {{ console.log('After screenshot failed:', e.message); }}                await browser.close();            }} catch (error) {{        console.error('ERROR:', error.message);        process.exit(1);    }}}})();'''        def send_message_to_open_chrome(self, contact: Contact, message: str, dry_run: bool = False) -> bool:        """Navigate existing Chrome to contact's conversation and type message"""                if dry_run:            print(f"\n[DRY RUN] Would send to: {contact.fb_name}")            print(f"Message: {message[:100]}...")            return True                try:            # Check if Chrome is still open, relaunch if closed            if not self.ensure_chrome_open(contact.messenger_url):                print("   Could not relaunch Chrome! Skipping...")                self.mark_contact_bad(contact, "Chrome not responding")                self.error_count += 1                return False                        print(f"\n[{self.sent_count + self.error_count + 1}] {contact.fb_name} — {contact.messenger_url}")            print("   Navigate + type + send automatically. Press 's' to skip, 'b' for bad, 'q' to quit.")            confirm = input("   Press ENTER to send, or s/b/q: ").strip().lower()                        if confirm == 's':                print("   Skipped.")                return False                        if confirm == 'b':                print("   Marked as bad.")                self.mark_contact_bad(contact, "User marked as bad")                return False                        if confirm == 'q':                print("   Quitting.")                return None                        # Run Playwright: navigate + type + send            print("   Sending...")                        script_content = self.create_playwright_script(message, contact.messenger_url, contact.fb_name)            temp_script = DATA_DIR / "temp_send.js"            temp_script.write_text(script_content, encoding='utf-8')                        result = subprocess.run(                ['node', str(temp_script)],                capture_output=True,                text=True,                encoding='utf-8',                errors='replace',                timeout=60,                cwd=str(DATA_DIR)            )                        stdout = result.stdout or ''            stderr = result.stderr or ''                        if result.returncode == 0:                print("   Sent!")                self.history.record_sent(contact, self.event.url, message)                self.update_csv_status(contact, success=True)                self.sent_count += 1                return True            elif result.returncode == 2 or 'ALREADY_SENT' in stdout:                print("   Already sent! Marking as sent.")                self.history.record_sent(contact, self.event.url, message)                self.update_csv_status(contact, success=True)                self.sent_count += 1                return True            else:                error = stderr or stdout or "Unknown error"                if any(x in error.lower() for x in ['not found', 'timeout', 'composer', 'textbox']):                    print(f"   Bad profile: {error[:50]}")                    self.mark_contact_bad(contact, error[:80])                else:                    print(f"   Failed: {error[:50]}")                    self.update_csv_status(contact, success=False, error=error[:80])                self.error_count += 1                return False                        except subprocess.TimeoutExpired:            print("\nTimeout - marking as bad profile")            self.mark_contact_bad(contact, "Timeout - page did not load")            self.error_count += 1            return False        except Exception as e:            print(f"\nError: {e}")            self.mark_contact_bad(contact, str(e))            self.error_count += 1            return False        finally:            temp_script = DATA_DIR / "temp_send.js"            if temp_script.exists():                temp_script.unlink()        def send_message(self, contact: Contact, message: str, dry_run: bool = False) -> bool:        """Send message to a contact"""                if dry_run:            print(f"\n[DRY RUN] Would send to: {contact.fb_name}")            print(f"Message: {message[:100]}...")            return True                chrome_process = None        try:            print(f"\n{'='*60}")            print(f"Opening Chrome for: {contact.fb_name}")            print(f"Messenger URL: {contact.messenger_url}")            print(f"{'='*60}")                        chrome_process = self.launch_chrome(contact.messenger_url)                        print("\nChrome is opening...")            print("\nINSTRUCTIONS:")            print("1. Wait for the Messenger page to load")            print("2. If you see a 'Continue' or 'Continue as' button, CLICK IT")            print("3. Wait for the conversation to fully load (see the message input box)")            print("4. Then come back here and press ENTER")            print("\nNOTE: Do NOT type the message - automation will do that!")            print(f"{'='*60}\n")                        # Wait for user to manually handle Continue button            confirm = input("👉 Press ENTER when you're ready for automation to type the message\n   (or 's' to skip this contact, 'q' to quit): ").strip().lower()                        if confirm == 's':                print("   Skipping this contact...")                return False                        if confirm == 'q':                print("   Quitting batch...")                return None  # Signal to quit batch                        # Now run Playwright to type the message            print("\n🤖 Connecting to Chrome and typing message...")                        script_content = self.create_playwright_script(message)            temp_script = DATA_DIR / "temp_send.js"            temp_script.write_text(script_content, encoding='utf-8')                        result = subprocess.run(                ['node', str(temp_script)],                capture_output=True,                text=True,                encoding='utf-8',                errors='replace',                timeout=120,                cwd=str(DATA_DIR)            )                        if result.returncode == 0:                print("\n✅ Message typed successfully!")                print("\n⚠️  IMPORTANT: Review the message in Messenger.")                print("   If it looks good, manually press Enter to send it.")                print("   Then close Chrome or press Enter here to continue.")                input("\n👉 Press ENTER when done...")                                self.history.record_sent(contact, self.event.url, message)                self.update_csv_status(contact, success=True)                self.sent_count += 1                return True            else:                error = result.stderr or "Unknown error"                print(f"\n❌ Automation failed: {error}")                print("\n   You may need to manually type the message.")                input("\n👉 Press ENTER when done...")                self.update_csv_status(contact, success=False, error=error)                self.error_count += 1                return False                        except subprocess.TimeoutExpired:            print("\n⏱️  Timeout - message may not have been sent")            input("\n👉 Press ENTER to continue...")            self.update_csv_status(contact, success=False, error="Timeout")            self.error_count += 1            return False        except Exception as e:            print(f"\n❌ Error: {e}")            input("\n👉 Press ENTER to continue...")            self.update_csv_status(contact, success=False, error=str(e))            self.error_count += 1            return False        finally